package thaumcraft.test;
import java.util.*;
import com.google.gson.*;
import com.mojang.serialization.JsonOps;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.thaumaturgy.*;
import thaumcraft.aura.*;
import thaumcraft.crystals.*;
import thaumcraft.research.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class BatRiftProbe {
    public static final BlockPos Q=new BlockPos(64,205,8),H=Q.east(4);public static final UUID OWNER=UUID.fromString("2e80cf72-894c-4db6-b309-bfe409e22236");
    static final BlockPos FAR=new BlockPos(32000,205,0);
    static ServerPlayer owner;static FocalEntity table;static boolean prepared,done;static int ticks;static long deadline;
    public static BlockState original(){return Blocks.OAK_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS,Direction.Axis.X);}
    public static FocusProgram graph(){return new FocusProgram("spellbat",List.of(new FocusProgram.Effect("heal",1,1)),"split_trajectory",2,10,1,5,true,List.of(new FocusProgram.Branch("bolt",List.of(new FocusProgram.Effect("rift",1,10,8)))));}
    public static void costs(ServerPlayer p,FocalEntity f){knowledge(p);p.experienceLevel=40;f.inventory.setItem(0,item("focus_3"));f.draft=graph();var menu=new FocalMenu(80,p.getInventory(),f);check(menu.clickMenuButton(p,13)&&!f.draft.friendly(),"Cannot choose hostile bat");check(menu.clickMenuButton(p,13)&&f.draft.friendly(),"Cannot choose friendly bat");check(menu.clickMenuButton(p,8)&&menu.clickMenuButton(p,3)&&f.draft.branches().getFirst().effects().getFirst().depth()==16,"Rift depth editor failed");check(menu.clickMenuButton(p,4)&&f.draft.branches().getFirst().effects().getFirst().duration()==2,"Rift duration did not wrap to two");f.draft=graph();int slot=1;for(var c:graph().crystals().entrySet())f.inventory.setItem(slot++,CrystalContent.essence(c.getKey(),c.getValue()));int before=p.experienceLevel;AuraManager.addVis(p.level(),Q,1000);check(f.start(p)&&p.experienceLevel==before-graph().levels(),"Combined bat/rift cost failed");check(!f.edit(p,3,1),"Pending rift settings changed");}
    public static void journalChecks(ServerLevel l){var d=new RiftData();for(int i=0;i<RiftData.MAX_OWNER;i++)check(d.reserve(new RiftData.Entry(H.offset(i,0,0).asLong(),original(),10000,OWNER)),"Cannot reserve bounded journal entry");check(d.available(OWNER)==0&&!d.reserve(new RiftData.Entry(H.above().asLong(),original(),10000,OWNER)),"Owner journal cap bypassed");for(int i=RiftData.MAX_OWNER;i<RiftData.MAX_HOLES;i++)check(d.reserve(new RiftData.Entry(H.offset(i,0,0).asLong(),original(),10000,new UUID(1,i/RiftData.MAX_OWNER))),"Cannot fill global bounded journal");check(!d.reserve(new RiftData.Entry(H.above(2).asLong(),original(),10000,UUID.randomUUID())),"Global journal cap bypassed");var codec=RiftData.TYPE.codec();var json=codec.encodeStart(JsonOps.INSTANCE,d).getOrThrow().getAsJsonObject();var duplicate=json.deepCopy();duplicate.getAsJsonArray("holes").set(1,duplicate.getAsJsonArray("holes").get(0));check(codec.parse(JsonOps.INSTANCE,duplicate).error().isPresent(),"Duplicate journal partially accepted");var future=json.deepCopy();future.addProperty("version",2);check(codec.parse(JsonOps.INSTANCE,future).error().isPresent(),"Future journal version partially accepted");var invalid=json.deepCopy();invalid.getAsJsonArray("holes").get(0).getAsJsonObject().add("original",JsonParser.parseString("{\"Name\":\"minecraft:chest\"}"));check(codec.parse(JsonOps.INSTANCE,invalid).error().isPresent(),"Inventory state journal accepted");var self=json.deepCopy();self.getAsJsonArray("holes").get(0).getAsJsonObject().add("original",JsonParser.parseString("{\"Name\":\"thaumcraft:hole\"}"));check(codec.parse(JsonOps.INSTANCE,self).error().isPresent(),"Self-restoring hole journal accepted");check(codec.parse(JsonOps.INSTANCE,json).getOrThrow().available(OWNER)==0,"Journal quota did not persist");check(ResearchCatalog.BY_KEY.get("FOCUSSPELLBAT").parents().contains("!minecraft:blaze"),"Spellbat research still requires an unavailable firebat");Thaumcraft.LOGGER.info("BAT_RIFT_JOURNAL_RULES_OK: quota, exact state codec, duplicate/future/inventory rejection and reachable research");}
    @SubscribeEvent public static void start(ServerStartedEvent e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("bat-rift-write")&&!mode.equals("bat-rift-read"))return;var l=e.getServer().overworld();l.setChunkForced(4,0,true);l.setChunkForced(4,1,true);owner=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"BatRiftProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};owner.setPos(64.5,206,8.5);if(mode.equals("bat-rift-read")){journalChecks(l);table=(FocalEntity)l.getBlockEntity(Q);check(table!=null&&table.working()&&table.remaining()<table.total()&&table.draft.equals(graph()),"Combined focus failed to resume");var entries=RiftData.get(l).entries();check(entries.stream().anyMatch(x->x.pos()==H.asLong()&&x.original().equals(original())&&x.owner().equals(OWNER)),"Rift restoration journal lost exact state/owner");deadline=entries.stream().filter(x->x.pos()==H.asLong()).findFirst().orElseThrow().deadline();}else{l.setBlockAndUpdate(Q,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(Q,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(Q);}}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(done||(!mode.equals("bat-rift-write")&&!mode.equals("bat-rift-read"))||++ticks<40)return;var l=e.server().overworld();if(mode.equals("bat-rift-read")){if(ticks==40){var bats=l.getEntitiesOfClass(SpellBat.class,new AABB(Q).inflate(12));check(bats.stream().anyMatch(b->OWNER.equals(b.ownerId())&&b.friendly()&&b.strikes()==5&&b.program().equals(graph().path(0))&&b.expires()>l.getGameTime()),"Bat owner, uses, program or lifetime lost across restart");check(l.getBlockState(H).is(ThaumaturgyContent.HOLE.get()),"Rift closed before persisted deadline");check(!l.hasChunkAt(FAR)&&RiftData.get(l).entries().stream().anyMatch(x->x.pos()==FAR.asLong()&&x.deadline()<=l.getGameTime()),"Expired unloaded hole was forced into memory or forgotten");l.setChunkForced(2000,0,true);}if(table.working()||l.getGameTime()<deadline+5)return;check(l.getBlockState(FAR).equals(original())&&l.getBlockState(H).equals(original())&&l.getBlockState(H.east()).is(Blocks.DIRT),"Rift restoration failed or overwrote later edit");check(table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get()).equals(graph()),"Combined focus output changed");done=true;Thaumcraft.LOGGER.info("BAT_RIFT_RESTART_OK: paused bat persisted, exact rift deadline/state and unloaded chunk restored, later edit preserved and combined focus completed once");e.server().halt(false);return;}
        if(!prepared){journalChecks(l);costs(owner,table);for(var bat:l.getEntitiesOfClass(SpellBat.class,new AABB(Q).inflate(12)))bat.discard();var bat=new SpellBat(ThaumaturgyContent.SPELLBAT.get(),l);bat.configure(owner,graph().path(0),Vec3.atCenterOf(Q.above(2)),.75F);l.addFreshEntity(bat);var d=RiftData.get(l);for(var pos:List.of(H,H.east()))l.setBlockAndUpdate(pos,original());d.restore(l);long deadline=l.getGameTime()+180;for(var pos:List.of(H,H.east())){l.setBlockAndUpdate(pos,original());check(d.reserve(new RiftData.Entry(pos.asLong(),original(),deadline,OWNER)),"Cannot reserve restart rift");l.setBlockAndUpdate(pos,ThaumaturgyContent.HOLE.get().defaultBlockState());}l.setBlockAndUpdate(H.east(),Blocks.DIRT.defaultBlockState());l.setChunkForced(2000,0,true);l.setBlockAndUpdate(FAR,original());check(d.reserve(new RiftData.Entry(FAR.asLong(),original(),l.getGameTime()+40,OWNER)),"Cannot reserve unloaded restart hole");l.setBlockAndUpdate(FAR,ThaumaturgyContent.HOLE.get().defaultBlockState());l.setChunkForced(2000,0,false);prepared=true;return;}if(table.remaining()==table.total())return;done=true;Thaumcraft.LOGGER.info("BAT_RIFT_WRITE_OK: saved live friendly bat, exact rift journal/deadline and paid combined focus");e.server().halt(false);
    }
}
